 }\n  if (isNanValue(operation.operand)) {\n    return operation.operand;\n  }\n  if (isNanValue(previousValue)) {\n    return previousValue;\n  }\n  return compareNumbers(operation.operand, previousValue) < 0\n    ? operation.operand\n    : previousValue;\n}\n\nexport function applyNumericMaximumTransformOperationToLocalView(\n  operation: NumericMaximumTransformOperation,\n  previousValue: ProtoValue | null\n): ProtoValue {\n  if (!isNumber(previousValue)) {\n    return operation.operand;\n  }\n  if (isNanValue(operation.operand)) {\n    return operation.operand;\n  }\n  if (isNanValue(previousValue)) {\n    return previousValue;\n  }\n  return compareNumbers(operation.operand, previousValue) > 0\n    ? operation.operand\n    : previousValue;\n}\n\nfunction asNumber(value: ProtoValue): number {\n  if (isIntegerValue(value)) {\n    return normalizeNumber(value.integerValue);\n  }\n  if (isDoubleValue(value)) {\n    return normalizeNumber(value.doubleValue);\n  }\n  if (isInt32Value(value)) {\n    return normalizeNumber(\n      value.mapValue!.fields![RESERVED_INT32_KEY]!.integerValue!\n    );\n  }\n  if (isDecimal128Value(value)) {\n    return parseFloat(\n      value.mapValue!.fields![RESERVED_DECIMAL128_KEY]!.stringValue!\n    );\n  }\n  return 0;\n}\n\nfunction coercedFieldValuesArray(value: ProtoValue | null): ProtoValue[] {\n  return isArray(value) && value.arrayValue.values\n    ? value.arrayValue.values.slice()\n    : [];\n}\n","/**\n * @license\n * Copyright 2017 Google LLC\n *\n * Licensed under the Apache License, Version 2.0 (the \"License\");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n *\n *   http://www.apache.org/licenses/LICENSE-2.0\n *\n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an \"AS IS\" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n\nimport { SnapshotVersion } from '../core/snapshot_version';\nimport { Timestamp } from '../lite-api/timestamp';\nimport { Value as ProtoValue } from '../protos/firestore_proto_api';\nimport { debugAssert, hardAssert } from '../util/assert';\nimport { arrayEquals } from '../util/misc';\nimport { SortedSet } from '../util/sorted_set';\n\nimport { Document, MutableDocument } from './document';\nimport { DocumentKey } from './document_key';\nimport { FieldMask } from './field_mask';\nimport { ObjectValue } from './object_value';\nimport { FieldPath } from './path';\nimport {\n  applyTransformOperationToLocalView,\n  applyTransformOperationToRemoteDocument,\n  computeTransformOperationBaseValue,\n  TransformOperation,\n  transformOperationEquals\n} from './transform_operation';\n\n/** A field path and the TransformOperation to perform upon it. */\nexport class FieldTransform {\n  constructor(\n    readonly field: FieldPath,\n    readonly transform: TransformOperation\n  ) {}\n}\n\nexport function fieldTransformEquals(\n  left: FieldTransform,\n  right: FieldTransform\n): boolean {\n  return (\n    left.field.isEqual(right.field) &&\n    transformOperationEquals(left.transform, right.transform)\n  );\n}\n\nexport function fieldTransformsAreEqual(\n  left?: FieldTransform[],\n  right?: FieldTransform[]\n): boolean {\n  if (left === undefined && right === undefined) {\n    return true;\n  }\n\n  if (left && right) {\n    return arrayEquals(left, right, (l, r) => fieldTransformEquals(l, r));\n  }\n\n  return false;\n}\n\n/** The result of successfully applying a mutation to the backend. */\nexport class MutationResult {\n  constructor(\n    /**\n     * The version at which the mutation was committed:\n     *\n     * - For most operations, this is the updateTime in the WriteResult.\n     * - For deletes, the commitTime of the WriteResponse (because deletes are\n     *   not stored and have